mapper.select:
SELECT * FROM wf_process_definition
WHERE process_key = #{processKey} AND tenant_id = #{tenantId}
ORDER BY definition_id FOR UPDATE

mapper.update:
UPDATE wf_form_draft SET title = #{draft.title}, form_data = #{draft.formData},
    node_assignees = #{draft.nodeAssignees}, last_save_time = #{draft.lastSaveTime},
    expire_time = #{draft.expireTime}, update_by = #{draft.updateBy}, update_time = #{draft.updateTime},
    lock_version = lock_version + 1
WHERE tenant_id = #{draft.tenantId} AND user_id = #{draft.userId} AND draft_id = #{draft.draftId}
  AND lock_version = #{expectedVersion}

mapper.delete:
DELETE FROM wf_form_draft
WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND draft_id = #{draftId}
  AND lock_version = #{expectedVersion}

mapper.select:
SELECT draft_id, tenant_id, lock_version, expire_time FROM wf_form_draft
WHERE tenant_id = #{tenantId} AND expire_time <= #{cutoff}
ORDER BY expire_time, draft_id LIMIT 500

mapper.delete:
DELETE FROM wf_form_draft
WHERE tenant_id = #{tenantId} AND draft_id = #{draftId} AND lock_version = #{expectedVersion}
  AND expire_time <= #{cutoff}
